import 'package:flutter/material.dart';
void main()=>runApp(const PetApp());
class Pet { final String name,type,image; final double rating; const Pet(this.name,this.type,this.image,this.rating); }
const pets=[Pet('Bella','Dog','https://images.unsplash.com/photo-1552053831-71594a27632d',4.9),Pet('Milo','Cat','https://images.unsplash.com/photo-151猫',4.8),Pet('Coco','Rabbit','https://images.unsplash.com/photo- Lisa',4.6),Pet('Charlie','Dog','https://images.unsplash.com/photo-1543466835-00a7907e9de1',4.7)];
class PetApp extends StatelessWidget { const PetApp({super.key}); @override Widget build(BuildContext context)=>const MaterialApp(debugShowCheckedModeBanner:false,home:PetHome()); }
class PetHome extends StatelessWidget { const PetHome({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Pet Adoption Explorer')),body:ListView(children:[for(final pet in pets)Card(child:ListTile(leading:Hero(tag:pet.name,child:Image.network(pet.image,width:70,height:70,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.pets,size:40))),title:Text(pet.name),subtitle:Text('${pet.type} • ⭐ ${pet.rating}'),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>PetDetails(pet:pet)))))])); }
class PetDetails extends StatelessWidget { final Pet pet; const PetDetails({super.key,required this.pet}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(pet.name)),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Expanded(child:Hero(tag:pet.name,child:Image.network(pet.image,fit:BoxFit.contain,errorBuilder:(_,__,___)=>const Icon(Icons.pets,size:120)))),Text(pet.name,style:Theme.of(context).textTheme.headlineMedium),Text('${pet.type} • ⭐ ${pet.rating}'),const SizedBox(height:20),ElevatedButton(onPressed:()=>Navigator.pop(context,'Adoption interest sent for ${pet.name}!'),child:const Text('Adopt Me'))]))); }
